pattern('multi-ledger','把一次胜利拆成不同主体的账','战役胜、个人名次、城权、具名死亡和恢复可同时异向。',['先列主目标与其他主体目标','逐项指定结算渠道','按系统/现场分别关闭','保仍未达的目标进入下一段'],'当个人能高光但不能控制全部制度结果时。','用主MVP代所有人胜，或用全城奖恢复抹死者。','改成不同制度和非军事实体：项目成功/病人获救/家庭负债各由不同人承担。',['arena','emperor','capital','warreward','revenge'],[1004,1054,1089,1094,1157])
pattern('costed-power','强力需材料、运输和适合目标','把武器规模、使用条件与战术窗口接起来，避免无代价升级。',['给不可替代材料或身体门槛','展示搬运/维护','在一场实测中证优势','再给无法适用的空间/并发场景'],'能力能被环境、后勤或预算约束的组织故事。','只声称稀缺却下一场无限装备；强炮直接轰混战而无友军风险。','不用龙晶/炮名，换成需要冷链的药、低频能量或受法规限制的设施。',['cannon','bones','sea'],[1145,1156,1170])
pattern('mission-aftercare','系统闭环与道德后果错开','任务成功关一个条件，选择带来的债务另开而非暗改原任务没完。',['定义可完成任务','完成并发奖','保受影响的具体人物','让其后态要求新行动'],'成功目标确实局部而角色有额外承诺时。','把回收不全说系统作假，或奖励后立刻免除屠城责任。','用合同验收与照料责任、调查结案与受害者生活等重写，另造因果与价值。',['moon','lan','warreward','dragons'],[1071,1074,1107,1108,1178,1179])
pattern('return-gates','信任重建经过多道可验门','身份公开、临时协作、正式权利和共同生活分别有动作。',['让当事人本人认身份','给有限而清楚的临时权限','共同承受一次风险','正式制度接纳后再展示私生活变化'],'旧关系破裂且跨组织/地域回归不可能一句完成。','把道歉/回国计划等同所有成员信任或会籍生效。','换成离队研究员、家族继承或救援组织，不复制多别名/葡籍桥。',['return','bones','revenge'],[1086,1087,1091,1109,1141,1157])
pattern('material-chain','取得与失去构成装备选择','同一提升有原物、转交、资格和失旧效果，能力才不无限叠加。',['标原持有与旧功能','让人物主动取舍','记录复制/消耗/交付','安排首次实用验证'],'有可追物品与明确使用门槛的成长故事。','用称谓滑移造额外宝物，或把转交中的东西先写他已装。','改成权利许可、记忆媒介或工作工具，改变不可逆代价和测试办法。',['copy','souls','auction'],[1110,1111,1127,1138,1178,1179])
pattern('narrow-test','把抽象突破拆成小测试','修行成长可由外部反馈、动作数量和真实耗竭看见。',['先用失败暴露短板','教可独立练的最小动作','给测量或对手反馈','逐加并发后验收','恢复代价留在下一场'],'人物已有基础但某能力掌握不完整；师者能控制训练风险。','声称痛不伤却偷偷致命，或数据上升没有动作/体能对应。','用音乐协调、医疗操作或多通道感知等重写，不照搬温度/火甲片数。',['assault','training'],[1160,1161,1164,1165,1166])
pattern('window-team','让短窗口有明确创造者和接手者','群战通过两秒/一秒的可操作条件体现配角价值。',['给敌连招或不可见弱点','由一个配角付出代价开窗','另一人立刻接动作','展示超并发或错时仍失败'],'队伍具互补能力，胜负取决协作时序。','把开窗者死亡当零代价，或一招控制后所有强敌都不再抵抗。','将战斗转协作潜入/救灾，窗口由机械故障或人际许可产生。',['lastfan','lan','stealth','kill'],[1080,1081,1097,1120,1177])
pattern('channel-evidence','把怀疑、见证和定责分层','第一人称再确信，也需要独立后证才能改变责任结论。',['明确信息发言/取得者','写能证范围','让行动取得新证但保未证环','更新而不抹旧推断'],'主角有情感偏向且调查/政治信息分散的叙述。','让强烈语气自动变全知，或因证据不足否认已亲见袭击。','换成历史档案/职场事故，重新设计证据物、获证代价与误判。',['clue','assault','lamp'],[1141,1144,1152,1159,1160,1161])
pattern('double-threat','让既有优势因目标空间失效','炮能轰密兵却不能轰混战神骨，通过转换目标找回价值。',['把两个威胁放在不同位置','让同一工具对一方有效而另一方危险','分派不同队伍处理','保支援后仍有人损'],'能力强但存在友军/射线/覆盖边界的多线战。','只用更大伤害解全部，或忘记已有强炮无解释。','用法律证据、医疗隔离或救援设备做空间/权限分工。',['bomb','bones','sea'],[1153,1156,1170])
pattern('retreat-choice','撤退是目标重新排序','弃海岸/先撤三军/玩家护炮，把保全对象明确为可选责任。',['展示继续守的真实成本','明确最需保的资源/人群','分断后与撤离先后','给实际撤到和断后损失'],'组织拥有不同补充速度和移动能力，守地并非唯一胜利条件。','把可复活者写不痛不损，或宣布撤离但永不验到达。','换成医院撤院、流民移城，给被留下者的选择与反对空间。',['north','coast','lamp'],[978,979,1149,1152,1155])
pattern('resource-loop','资源胜利会改造下一轮敌我关系','主城补给造成升级差，夺岛再挤敌联手，不是胜后永远静止。',['让上一胜利产生任务/补给收益','收益具体影响下次战力','展示败方改立足地与结盟','保联盟尚未完成的现实条件'],'长期竞争有资源积累而非纯单次比武。','把等级差归族群天性，或一次败退就宣敌永久消失。','改成商帮、学院或边境部落，重造资源与合作成本。',['revive','land','diplomacy'],[1152,1171,1173])
pattern('consent-ledger','救助获益和主体同意不能互代','保护者可以带来真实好处，同时施加强迁或神智脆弱时的绑定。',['写清受助者实际收益','展示其是否可知情拒绝','记录控制手段与他人授权','让反应或后果保留张力'],'不对等权力下的契约、收容与资源迁移。','把母亲/组织许可当本人充分同意，或为批判而否认救命确实发生。','换成记忆保险、医疗代理/灵魂寄居，给受助者主动协商和撤回权的新路径。',['forced','blood','dragons'],[1074,1163,1175,1178])
pattern('dialogue-deal','对话条款必须有交付链','数字与条件落到收物、使用或失败，而非关系好便算履约。',['双方明确需求/对价','安排能取得稀缺物的人','给接收者确认','分别保下单/交到/实装'],'交易对象有具体可核物或权限。','以合同/估价作现金已入，把将来请求写现成资源。','更换对价为服务、信息或时间，发明新的验证与违约结果。',['ring','diplomacy','revenge','auction'],[1109,1110,1157,1168,1179])
pattern('controlled-unknown','只留下缺特定最后一步的悬念','卷末竞价、新君王排将和封神计划分别缺不同条件。',['识别已经关闭的局部任务','写下一步具体缺什么','限定哪位人物知道多少','止在本卷实际时间'],'多线长篇需要既有收获又有可追下一目标。','每章机械标一项未知，或借后卷结局让当下全知。','换掉拍卖/龙神框架，保缺落槌/证书/抵达等不同完成事件。',['auction','kill','dragons'],[1175,1178,1179])
pattern('relief-failure','日常小败让强者回到人的尺度','气枪校准后全中/夹娃娃全空，照护脱衣与饥饿承接大战。',['高压之后换低风险目标','保与职业相关的长处','在另一小事遭明确失败','用他人照护或笑声收束'],'人物刚经历大胜/重伤，需重新接入日常关系。','用性化羞辱取代真实互动，或以失败嘲弄消除此前创伤。','用烹饪、修理或礼仪误差，改变笑点对象和照料方式。',['assault','training','fly'],[1158,1165,1166,1174])
pattern('enemy-motive','敌方拒降理由保留镜像责任','安娜因子孙被杀拒降，与子舒复仇并置；枫指出主借魔历史。',['让敌指出一件真实相关动作','核实可证部分而不接全套辩护','给可拒的具体条件','由其本人选择和承担结局'],'敌我都使用类似手段而价值立场不同的冲突。','一句洗白敌全部暴行，或把敌悲痛直接当撒谎不记录。','将镜像从族群复仇改成资源保护/契约义务，重设可接受的和解条件。',['borrow','revive','kill'],[1071,1151,1177])
